# Video scripts for Module 2 (Special Newborn Care). Narration from the manual; (FG) = facilitator guide.
S = {}
def v(code, title, film, narration, length='2–3 minutes', note=''):
    S[code] = dict(title=title, film=film, narration=narration, length=length, **({'note': note} if note else {}))

v('SN2.2.1', 'Signs of illness in newborns',
  ['Short clinical clips (with consent): fast breathing, slow breathing, chest indrawing, grunting, a seizure, pustules and bullae, umbilical redness, pallor, a floppy baby.',
   'Using a thermometer: axillary placement and reading.'],
  ['Triage is a quick assessment and sorting process used to evaluate and categorize sick newborns shortly after they arrive.',
   'The key signs of illness: poor feeding; decreased activity or altered consciousness; fast breathing, over 60 a minute; slow breathing, under 40 a minute; chest indrawing; grunting; seizures; a bulging fontanelle.',
   'Look for evidence of circulatory impairment: capillary refill time, blood pressure, pulse rate and volume. Look for floppiness or stiffness.',
   'Fever is above 37.5 °C; hypothermia is below 36.5 °C.',
   'Look at the umbilicus for discharge, bleeding or redness, and at the skin for more than 10 pustules or bullae, or any swelling, redness or hardness. Look for pallor.'],
  note='The manual itself asks for this video ("A video showing fast breath, slow breath, chest indrawing, seizures, pustules and bullae").')
v('SN2.3.1', 'Receiving a newborn in the SCNU',
  ['The admission incubator pre-warmed, trolley, monitor and respiratory support ready.', 'The baby arrives: three staff work at the same time: handover, rapid assessment, warmth and monitoring.'],
  ['Immediately on receiving a call about an expected admission, an admission team is organised and prepares the baby\'s place: a functioning, pre-warmed incubator or warmer, the admission trolley, the vital signs monitor, the respiratory support asked for, and the admission file.',
   'When the baby arrives, the next steps are done at the same time.',
   'Handover: a thorough handover from the transferring unit, including the baby\'s condition, medicines and special needs. Each staff member, medical and nursing, receives their own handover.',
   'Assessment: vital signs, heart rate, breathing and admission temperature, a physical examination and initial tests. Growth measurements can wait until the baby is stable.',
   'Maintaining stability: monitoring vital signs, oxygen saturation and temperature; warmth; incubator temperature and humidity; respiratory support; blood glucose.',
   '(FG) Use a checklist so nothing is missed.'])
v('SN2.4.1', 'Moving a baby from incubator to cot',
  ['A stable preterm moved from an incubator to a cot; clothing, blanket, temperature checks on screen hour by hour.'],
  ['Standard cots are used for routine care of term and late preterm babies, and for weaning preterm and sick babies from incubators or warmers.',
   'After moving to a cot, check the temperature every hour, four times. If it is between 36.2 and 36.5 °C, add clothing layers and a pre-warmed blanket.',
   'Continue hourly checks until the axillary temperature is 36.5 °C or more for 4 hours in a row.',
   'If the temperature is below 36.5 °C on 3 hourly checks in a row, return the baby to a pre-warmed incubator.',
   'Defer bathing until the temperature has stayed at 36.5 °C or more for at least 12 hours after the move.'])
v('SN2.4.2', 'Working out fluids and the glucose infusion rate', ['Whiteboard animation.'],
  ['The starting fluid on day 1 depends on birth weight: under 1000 grams, 100 to 150 ml per kg per day; 1000 to 1500 grams, 80 to 100; over 1500 grams, 60 to 80.',
   'Monitor fluids with daily weight, fluid balance, urine output and serum sodium.',
   'The glucose infusion rate, in mg per kg per minute, equals the IV rate in ml per hour, times the dextrose concentration, times 1000, divided by the weight in kg, times 60, times 100.',
   'Example: a 2 kg baby on 10% dextrose at 7.2 ml an hour: 7.2 times 10 times 1000, divided by 2 times 60 times 100, is 6 mg per kg per minute.',
   'Start at 4 to 6 mg per kg per minute in preterm and 6 to 8 in term neonates, increasing gradually up to 12 according to the baby\'s condition, and keep glucose at 50 to 110 mg per dl.'], length='3 minutes')
v('SN2.5.1', 'Estimating gestational age with the New Ballard score',
  ['A settled baby (or manikin) lying supine. Each neuromuscular sign shown and scored, then each physical sign.', 'Adding the scores and reading the maturity rating; plotting weight and length.'],
  ['Obtain a gestational age score on all babies weighing less than 2000 grams, within 24 hours of delivery, when the baby is settled.',
   'Neuromuscular signs, with the baby supine, awake but not crying: posture; square window, the angle of the flexed wrist; arm recoil; popliteal angle; scarf sign; heel to ear. Assessing both sides improves accuracy.',
   'Physical signs: skin; lanugo on the back; plantar creases, noting only definite creases; breast appearance and bud size; ears and eyes; genitalia.',
   'Add the neuromuscular and physical scores and read the maturity rating in weeks from the conversion table.',
   'Then plot the weight and length on the growth chart, and record whether the baby is appropriate, small or large for gestational age.'], length='4 minutes')
v('SN2.5.2', 'Phototherapy: setting it up and caring for the baby',
  ['A jaundiced baby under phototherapy: undressed except a small nappy, eyes covered, light about 45 cm above; turning, breastfeeding, temperature checks.'],
  ['Phototherapy exposes the skin of the jaundiced baby to blue light of wavelength 450 to 460 nm.',
   'Follow hand hygiene. Keep the baby warm and take the axillary temperature at least every 2 to 4 hours.',
   'Remove all the baby\'s clothes except a small nappy, and cover the eyes and gonads.',
   'Position the lights above the cot, incubator or warmer, about 45 cm from the baby, with the baby in the centre.',
   'Continue frequent breastfeeding. Change the baby\'s position after each feed or 2-hourly.',
   'Monitor the bilirubin at least once in 24 hours.'])
v('SN2.6.1', 'Kangaroo mother care: positioning step by step',
  ['A mother in a private, warm KMC area (22–24 °C) with her small baby; the 17 steps of the manual followed in order.'],
  ['Kangaroo mother care is skin-to-skin contact with the mother, father or caregiver, and exclusive, frequent breastfeeding, for babies under 2000 grams.',
   'Explain the procedure. The mother washes and dries her hands. Provide a comfortable chair and privacy, and keep resuscitation equipment near.',
   'Attach the pulse oximeter and check the baby\'s temperature.',
   'Undress the baby, leaving only the nappy and hat. The mother loosens the front of her clothes.',
   'Place the baby upright between the mother\'s breasts, the head turned to one side with the ear over the heart so the nose is not blocked.',
   'Button up the mother\'s clothes over the baby, add a sheet if needed, and keep cables and lines untangled.',
   'Start with 30 minutes once a day, then 2 to 3 times a day for 2 to 3 hours, as long as the mother is willing. Observe throughout at first.',
   'At the end, return the baby to the incubator, check the temperature and compare, wash hands, and document.'], length='4 minutes')
for code, title, film, narr in [
    ('SN2.7.1', 'Preventing pain during procedures', ['A heel prick in a swaddled baby given sucrose 2 minutes before; skin-to-skin after.'],
     ['Cluster painful interventions before comforting events such as feeding or holding.', 'During the procedure: swaddling, non-nutritive sucking, a diaper change.',
      'Glucose analgesia: 25 to 30% sucrose, 1.5 to 3 ml by mouth about 2 minutes before the procedure in term newborns; 25% sucrose, 0.5 to 1.5 ml, in preterm newborns. Suckling the nipple is analgesia for venepunctures.',
      'After the procedure: reduce noise and light; touch or massage; skin-to-skin contact; hold the baby with blanket rolls.']),
    ('SN2.7.2', 'Umbilical artery catheterization', ['Manikin or consented procedure, sterile field; each step of the manual\'s UAC procedure.'],
     ['Indications: blood pressure and blood gas monitoring through the umbilical artery in critically ill neonates. Contraindications: omphalitis, peritonitis, suspected NEC, intestinal hypoperfusion.',
      'Catheter: 3.5 French under 1.5 kg, 5 French at 1.5 kg or more. UAC high line length in cm is 3 times the birth weight in kg, plus 9. A high line tip lies between T6 and T9.',
      'Keep the baby warm. Prepare and drape the cord. Flush the catheter with saline, with no air bubbles.',
      'Tie umbilical tape around the base of the cord; cut the cord 1.5 to 2 cm from the skin. Identify the one large thin-walled vein and the two smaller thick-walled arteries.',
      'Dilate one artery gently with the forceps. Insert the catheter, aiming toward the feet, and advance to the measured distance. Do not force.',
      'Confirm the tip by X-ray or ultrasound and secure the catheter. It may be pulled back but not advanced once the sterile field is broken.',
      'Watch for blanching or cyanosis of the legs; remove the catheter if complications occur. Never use hypo-osmolar fluids in the artery.']),
    ('SN2.7.3', 'Umbilical vein catheterization (UVC)', ['Manikin or consented procedure; each step of the UVC procedure.'],
     ['Indications include urgent IV access, babies under 1000 grams, 28 weeks or less, ventilated babies or FiO₂ above 40% on CPAP, exchange transfusion, haemodynamic instability, and hypertonic solutions.',
      'UVC length in cm is half the UAC high-line length, plus 1. The tip should lie in the inferior vena cava, above the ductus venosus and below the right atrium.',
      'Prepare and drape, flush the catheter, tie the cord and cut it 1.5 to 2 cm from the skin.',
      'Isolate the thin-walled vein, clear thrombi, and insert the catheter. Apply gentle suction as you advance. Once blood flows back freely, usually after 5 to 7 cm, do not advance further. Do not infuse into the liver.',
      'Tie and secure the catheter, connect the infusion without air bubbles, and confirm the tip by X-ray or ultrasound.',
      'If redness or swelling appears around the umbilicus, stop the infusion, remove the catheter and treat for infection.']),
    ('SN2.7.4', 'Inserting a PICC line', ['Aseptic PICC insertion in a manikin arm or a consented baby.'],
     ['A PICC is used when IV access is needed for a long time, more than 6 days.',
      'Measure the insertion distance: upper limb or head to the suprasternal notch; lower limb to the umbilicus.',
      'Full aseptic precautions: gown, sterile gloves, drapes from head to toe. Flush the line with 0.9% sodium chloride. Let the antiseptic dry completely.',
      'Insert the introducer until flashback, then advance the line gently with non-toothed forceps, no further than the measured distance.',
      'Remove the introducer, press until oozing stops, secure with a steristrip and cover all the line with a transparent dressing, including the junction.']),
    ('SN2.7.5', 'Intraosseous access', ['Manikin leg; insertion at the proximal tibia.'],
     ['In an emergency, when IV access is difficult, the bone marrow cavity is a good temporary route for fluids and drugs.',
      'First site: the flat anteromedial surface of the proximal tibia, 1 to 2 cm below and slightly medial to the tibial tuberosity.',
      'Bend the knee about 30 degrees with the heel on the table. Insert an 18-gauge IO needle perpendicular to the skin, away from the growth plate, and with a boring rotary motion go through the cortex until the resistance falls. The needle should stand firmly.',
      'Slowly inject 3 ml of fluid and look for swelling at the front of the leg or in the calf. If there is swelling, remove the needle and try again.',
      'Secure the needle and attach the IV tubing. Remove it as soon as other IV access is available, within eight hours if possible.']),
    ('SN2.7.6', 'Endotracheal intubation of a newborn', ['Manikin intubation, then a consented clinical clip if available; confirmation steps.'],
     ['Prepare: the intubation set should always be ready and checked.',
      'Hold the laryngoscope in the left hand. Insert the blade, push the tongue to the left, keep to the midline, and lift forward and upward. Do not lever against the gum.',
      'Use suction only if secretions block the view. Bring the vocal cords into view.',
      'Feed the tube in from the side so you see it pass through the cords. Use the black marker as a guide, then adjust to the naso-tragal length plus 1 cm.',
      'Confirm: chest rise, air entry on both sides, and a CO₂ detector. Secure the tube and ventilate.',
      'A chest X-ray is the gold standard: the tip should be 1 cm above the carina, at T2 to T3. Document and update the parents.']),
    ('SN2.7.7', 'Needle thoracotomy for tension pneumothorax', ['Manikin chest; landmarks and the needle with a saline-filled syringe.'],
     ['Indication: evacuation of a tension pneumothorax.',
      'Prepare the skin. Insert a large-bore angiocatheter into the anterior second intercostal space in the midclavicular line, over the top of the rib.',
      'With 1 to 2 ml of saline in the syringe, aspirate as you insert: a rush of bubbles shows you are in the air collection.',
      'Withdraw the needle, attach a three-way stopcock and syringe, and aspirate the air.',
      'A chest tube is then needed for ongoing release of air.']),
    ('SN2.7.8', 'Chest tube insertion and the drainage system', ['Manikin or simulation model; the underwater seal drain.'],
     ['Chest tube size: 8 to 10 French under 1500 grams, 10 to 12 French above.',
      'The landmark is the 4th or 5th intercostal space in the anterior mid-axillary line.',
      'Make the incision, dissect bluntly over the top of the rib, and enter the pleura with steady pressure. A rush of air or fluid confirms entry.',
      'Guide the tube in with the clamp; the last hole must be inside the chest. Secure with a suture, connect to the drainage system, and confirm with a chest X-ray.',
      'Keep the drain upright and below the chest. To remove, pull the tube quickly at peak inspiration and cover with an occlusive dressing; X-ray afterwards.']),
    ('SN2.7.9', 'Lumbar puncture in a newborn', ['Assistant holding the baby (or manikin) in the lateral position; landmarks; collection.'],
     ['Indication: to confirm meningitis. Defer in unstable babies and start treatment.',
      'Be ready to resuscitate. Place the baby under a radiant warmer.',
      'Lateral position with hips, knees and neck flexed, shoulders and hips aligned. Do not compromise the baby\'s breathing.',
      'Find L3 to L4 or L4 to L5 on the line between the tops of the iliac crests. Prepare the skin and drape.',
      'Insert the needle in the midline, angled towards the umbilicus. Advance a few millimetres at a time, removing the stylet to check for CSF.',
      'Collect three tubes: culture and Gram stain, then glucose and protein, then cell count. Press on the site until the leak stops.']),
    ('SN2.7.10', 'Urinary bladder catheterization', ['Manikin; male and female technique.'],
     ['Indications: a sterile urine sample, monitoring hydration, bladder decompression.',
      'Use a 6 French catheter. For a culture, the baby should not have voided in the past hour.',
      'Prepare the urethral opening with sterile technique. In boys, straighten the penis with gentle traction; in girls, the urethra is just above the vaginal opening.',
      'Insert the lubricated catheter gently; continued gentle pressure passes the external sphincter. Remove once the sample is obtained and clean the skin.']),
    ('SN2.7.11', 'Suprapubic bladder aspiration', ['Manikin or model in frog-leg position.'],
     ['Indications: a sterile urine sample, bladder decompression.',
      'The baby should not have voided in the past hour. Restrain in the supine frog-leg position.',
      'The site is 1 to 2 cm above the symphysis pubis in the midline.',
      'Use a 22-gauge needle at 10 to 20 degrees from the perpendicular, aiming slightly toward the feet, with gentle suction, no deeper than 3 cm.',
      'Remove the needle, clean the skin and apply a sterile bandage.']),
    ('SN2.8.1', 'Using a radiant warmer', ['The warmer, its parts, the control panel, the skin probe on a baby or manikin.'],
     ['Turn on the warmer 20 minutes before the baby comes, to pre-warm the linen and mattress.',
      'Manual mode is for preparing the bed and rapid warming of a severely hypothermic baby, with constant attention. Servo mode adjusts the heat automatically by skin temperature.',
      'Set the target temperature to 36.5 to 37.0 °C. Fix the skin probe over the right hypochondrium with the baby supine, or the flank when prone.',
      'Check the probe and record the temperature every 2 to 3 hours, and change the probe site every 24 hours.',
      'Never leave a baby unattended under a warmer in manual mode. One radiant warmer, one baby.']),
    ('SN2.8.2', 'Using the Embrace portable warmer', ['The AccuTemp heater, WarmPak and BabyWrap.'],
     ['Wash your hands and use a clean, disinfected BabyWrap.',
      'Plug in the AccuTemp heater and put the WarmPak inside for 30 minutes.',
      'Place the warmed WarmPak in the pouch of the BabyWrap, then place the baby inside.',
      'Use the Rainbow sign to monitor the target temperature. The WarmPak keeps the baby warm for 4 to 6 hours.',
      'After use, clean the BabyWrap with soap and water and disinfect the heater.']),
    ('SN2.8.3', 'Setting up an infant incubator', ['The incubator, its controls and reservoir.'],
     ['Make sure the incubator is clean and disinfected, connect it to a reliable power source and switch it on.',
      'Servo mode: set the skin temperature to 36.5 to 37 °C. Air mode: 34 to 36 °C for extremely preterm babies, 33 to 34 °C for very preterm, 32 to 33 °C for near-term and term.',
      'Attach the skin probe to the abdomen or back and change the site every 8 to 12 hours.',
      'Fill the reservoir with sterile or distilled water. Humidity usually starts at 40 to 70%, or 70 to 90% in the first week for babies under 1500 grams.',
      'Close all the doors, check the axillary temperature 2 to 4 times a day, and open the portholes as little as possible.']),
    ('SN2.8.4', 'Vayu bubble CPAP: assembly and disinfection', ['The Vayu parts laid out, assembled, then disassembled for cleaning.'],
     ['The main parts: the Vayu blender and pressure generator, humidifier and tube, reusable filter, rotator, breathing tubes and nasal prongs.',
      'Assemble according to the manufacturer\'s guidance. Refill the humidifier before it falls below the refill line, and the pressure generator below the fill mark.',
      'Replace the water in the jars and the filter disk every 24 hours. Make sure there is continuous bubbling at all times, and check the oxygen cylinder pressure.',
      'To disinfect: empty and disassemble, clean with detergent, brush and flush the lumens three times, then soak in 0.5% chlorine for 10 minutes or glutaraldehyde for 40 minutes. Rinse and flush three times, dry and store assembled. Never autoclave or boil.']),
    ('SN2.8.5', 'Pulse oximeter: standard operating procedure', ['Probe placement on a baby\'s foot or hand.'],
     ['Hand hygiene. Clean the probe with spirit and let it dry. Switch on.',
      'Apply the probe to a warm, well-perfused site, the two sides directly opposite each other, and secure it.',
      'Set the high and low alarm limits for saturation and heart rate.',
      'If on continuously, observe and change the site every 6 to 8 hours.',
      'It may not work in low perfusion, with abnormal haemoglobins, or with light from phototherapy, fluorescent lamps or sunlight.']),
    ('SN2.8.6', 'Setting up syringe and infusion pumps', ['A syringe pump and an infusion pump, step by step.'],
     ['Syringe pump: set the flow rate, load the syringe with the nozzle in its slot, slide the driver block to the plunger, secure the barrel.',
      'Press and hold PURGE to remove air from the syringe and tubing before connecting to the baby, then press RUN.',
      'Infusion pump: fill the drip chamber one third; place the tube through the air bubble and occlusion detectors; close the door; attach the drop sensor.',
      'Set the flow rate, the delivery volume and the time, then start. Before restarting, confirm the settings.']),
    ('SN2.8.7', 'Suctioning a newborn safely', ['Suction machine, catheter sizes, a manikin.'],
     ['Check the suction pressure by occluding the tubing with your thumb. It must not exceed 100 mm Hg.',
      'Use a disposable catheter: 4 to 5 French for a preterm baby, 6 French for a newborn.',
      'Use the lowest pressure, the smallest catheter and the shortest time. Insert only 5 cm in the mouth and suction while withdrawing, 10 to 15 seconds at a time.',
      'Stop if the heart rate falls by 20 or rises by 40 beats a minute, or with any ectopy. No more than 4 suctions per episode.',
      'Disinfect the collection bottle after each patient in chlorine or glutaraldehyde for 20 minutes.']),
    ('SN2.8.8', 'Bag and mask: checking, ventilating and cleaning', ['A manikin; mask fit and grip; the chest rising.'],
     ['Fit the mask over the nose and mouth and press firmly to prevent leaks: thumb on one side, index and middle fingers on the other.',
      'Squeeze the bag 30 to 60 times a minute. Ventilation is effective if the chest rises and falls.',
      'If the chest does not rise, check the bag–mask connection, the mask position and the head position. Too much pressure can cause a pneumothorax.',
      'Check every minute for breathing without taking the mask off. Continue until the baby breathes.',
      'Afterwards: rinse, wash, immerse in disinfectant for 20 minutes, rinse three times in distilled water and dry; or autoclave.']),
    ('SN2.10.1', 'Taking a blood culture from a newborn', ['A sterile blood culture collection on a manikin arm or a consented baby.'],
     ['Verify the identity, calm the baby and position for access.',
      'Clean the site with 70% alcohol for 30 seconds and let it air dry. Do not touch the site again.',
      'Use sterile gloves and a 23 to 25 gauge needle. Take 1 to 2 ml of blood per bottle; this volume is critical for detection.',
      'If the baby is already on antibiotics, take the culture immediately before the next dose.',
      'Label with the name, file ID, date and time, collector and sample type; complete the request form; record the sample in the case register.']),
    ('SN2.10.2', 'Hand hygiene: handrub and handwash, step by step', ['The WHO handrub and handwash steps, filmed close-up, with a timer.'],
     ['If hands are not visibly soiled, use alcohol-based handrub: enough to cover all areas of the hands, and rub until dry, 20 to 30 seconds.',
      'If hands are visibly soiled, wash with soap and water: rub all surfaces for 40 to 60 seconds, rinse, dry with a single-use towel and use the towel to turn off the tap.',
      'Keep nails short, no more than half a centimetre, and no artificial nails.',
      'Gloves are not a substitute for hand hygiene.']),
    ('SN2.10.3', 'Manual disinfection at the decontamination station', ['The four labelled containers on a 2-metre bench; disinfecting an Ambu bag.'],
     ['Prepare four containers: soap and water; water; 0.1% chlorine; sterile or filtered water.',
      'Collect the used items in gloves, wipe off secretions, and take everything apart.',
      'In heavy-duty gloves and PPE, wash each part under the water with brushes, then rinse in container 2.',
      'Put all the parts under the chlorine solution, cover, and wait 20 minutes. Move them with sterile forceps into the sterile water.',
      'Dry with sterile gauze, reassemble, check it works, store in a sterile container labelled "disinfected" with the date. Change the chlorine daily.']),
]:
    v(code, title, film, narr)
v('SN2.9.1', 'Identifying newborns and closed-loop orders',
  ['Two identification bands on a baby; a nurse matching the lab form to the bands; twins with similar names; a phone order read back.'],
  ['Newborns are at high risk of being misidentified: similar birth dates, similar names, twins, and they cannot say who they are.',
   'Use at least two patient identifiers. Name babies with the mother\'s names and the baby\'s sex, for example "Smith, Judy, Girl A" and "Girl B" for twins.',
   'Before taking blood, use a band attached to the baby, never the bed number or a band on the cot. Check the name, date of birth and file number on the form against the baby.',
   'Care providers read back their verbal orders for verification.'])
